  "clickable": "'use client';\n\nimport React, { useState } from 'react';\nimport { Divider, Steps } from '@ceebee/ui/client';\n\nconst App: React.FC = () => {\n  const [current, setCurrent] = useState(0);\n\n  const onChange = (value: number) => {\n    console.log('onChange:', value);\n    setCurrent(value);\n  };\n  const content = 'This is a content.';\n\n  return (\n    <>\n      <Steps\n        current={current}\n        onChange={onChange}\n        items={[\n          {\n            title: 'Step 1',\n            content,\n          },\n          {\n            title: 'Step 2',\n            content,\n          },\n          {\n            title: 'Step 3',\n            content,\n          },\n        ]}\n      />\n\n      <Divider />\n\n      <Steps\n        current={current}\n        onChange={onChange}\n        orientation=\"vertical\"\n        items={[\n          {\n            title: 'Step 1',\n            content,\n          },\n          {\n            title: 'Step 2',\n            content,\n          },\n          {\n            title: 'Step 3',\n            content,\n          },\n        ]}\n      />\n    </>\n  );\n};\n\nexport default App;\n\n",
